package com.pp.shaderlod.optimization.solasao;
import net.irisshaders.iris.targets.RenderTargets;import org.lwjgl.opengl.*;import java.util.*;
/** Actual current GL state only; preserves active texture; never allocates, repairs state or reads pixels. */
public final class SolasAoGlProof {
 public record Binding(int texture,int width,int height,int format,int depthBits,int depthType,int base,int min,int mag,int compare,int wrapS,int wrapT,float aniso){}
 public record Draw(SolasAoEpoch.Output output,boolean qualified){}
 private SolasAoGlProof(){}
 private static String failure;
 private static boolean proof(boolean accepted,String reason){if(!accepted&&failure==null)failure=reason;return accepted;}
 public static String diagnostic(){return failure==null?"no failed producer predicate":failure;}
 public static int integer(int program,String name){int l=GL20.glGetUniformLocation(program,name);return l<0?-1:GL20.glGetUniformi(program,l);}
 private static int parameter(int sampler,int p){return sampler==0?GL11.glGetTexParameteri(GL11.GL_TEXTURE_2D,p):GL33.glGetSamplerParameteri(sampler,p);}
 public static Binding binding(int program,String uniform){int unit=integer(program,uniform);if(unit<0||unit>=GL11.glGetInteger(GL20.GL_MAX_COMBINED_TEXTURE_IMAGE_UNITS))return null;
  int active=GL11.glGetInteger(GL13.GL_ACTIVE_TEXTURE);try{GL13.glActiveTexture(GL13.GL_TEXTURE0+unit);int texture=GL11.glGetInteger(GL11.GL_TEXTURE_BINDING_2D);if(texture<=0)return null;
   int sampler=GL11.glGetInteger(GL33.GL_SAMPLER_BINDING);var caps=GL.getCapabilities();boolean aniso=caps.GL_EXT_texture_filter_anisotropic||caps.GL_ARB_texture_filter_anisotropic;
   float anisotropy=aniso?(sampler==0?GL11.glGetTexParameterf(GL11.GL_TEXTURE_2D,0x84FE):GL33.glGetSamplerParameterf(sampler,0x84FE)):1;
   int width=GL11.glGetTexLevelParameteri(GL11.GL_TEXTURE_2D,0,GL11.GL_TEXTURE_WIDTH),height=GL11.glGetTexLevelParameteri(GL11.GL_TEXTURE_2D,0,GL11.GL_TEXTURE_HEIGHT),format=GL11.glGetTexLevelParameteri(GL11.GL_TEXTURE_2D,0,GL11.GL_TEXTURE_INTERNAL_FORMAT);
   int depthBits=0,depthType=0;
   if(format==GL11.GL_DEPTH_COMPONENT){depthBits=GL11.glGetTexLevelParameteri(GL11.GL_TEXTURE_2D,0,GL14.GL_TEXTURE_DEPTH_SIZE);depthType=GL11.glGetTexLevelParameteri(GL11.GL_TEXTURE_2D,0,GL30.GL_TEXTURE_DEPTH_TYPE);}
   return new Binding(texture,width,height,format,depthBits,depthType,GL11.glGetTexParameteri(GL11.GL_TEXTURE_2D,GL12.GL_TEXTURE_BASE_LEVEL),parameter(sampler,GL11.GL_TEXTURE_MIN_FILTER),parameter(sampler,GL11.GL_TEXTURE_MAG_FILTER),parameter(sampler,GL14.GL_TEXTURE_COMPARE_MODE),parameter(sampler,GL11.GL_TEXTURE_WRAP_S),parameter(sampler,GL11.GL_TEXTURE_WRAP_T),anisotropy);
  }finally{GL13.glActiveTexture(active);}}
 private static boolean base(Binding b){return b!=null&&b.base()==0&&b.compare()==GL11.GL_NONE&&b.aniso()==1&&Set.of(GL11.GL_NEAREST,GL11.GL_LINEAR).contains(b.min())&&Set.of(GL11.GL_NEAREST,GL11.GL_LINEAR).contains(b.mag());}
 private static boolean state(int p){java.nio.ByteBuffer mask=org.lwjgl.BufferUtils.createByteBuffer(4);GL11.glGetBooleanv(GL11.GL_COLOR_WRITEMASK,mask);for(int i=0;i<4;i++)if(mask.get(i)==0)return proof(false,"state color write mask");int loc=GL20.glGetUniformLocation(p,"gbufferProjection");float[] matrix=new float[16];if(loc<0)return proof(false,"state projection uniform missing");GL20.glGetUniformfv(p,loc,matrix);
  if(!proof(SolasAoContract.projection(matrix),"state projection")){failure+="; matrix="+Arrays.toString(matrix);return false;}
  return proof(integer(p,"shaderlodBridgeVersion")==2,"uniform shaderlodBridgeVersion")&&proof(integer(p,"shaderlodEnabled")==1,"uniform shaderlodEnabled")&&proof(integer(p,"shaderlodOptimizationFlagsVersion")==1,"uniform shaderlodOptimizationFlagsVersion")&&proof(integer(p,"shaderlodOptAoRenderScale")==1,"uniform shaderlodOptAoRenderScale")&&proof(Set.of(0,1,2).contains(integer(p,"shaderlodPreset")),"uniform shaderlodPreset")&&proof(integer(p,"frameCounter")>=0,"uniform frameCounter lower bound")&&proof(integer(p,"frameCounter")<16777216,"uniform frameCounter upper bound")&&
   proof(GL11.glGetInteger(GL20.GL_CURRENT_PROGRAM)==p&&GL20.glGetProgrami(p,GL20.GL_LINK_STATUS)==GL11.GL_TRUE&&
   !GL11.glIsEnabled(GL11.GL_SCISSOR_TEST)&&!GL11.glIsEnabled(GL11.GL_DEPTH_TEST)&&!GL11.glIsEnabled(GL11.GL_STENCIL_TEST)&&!GL11.glIsEnabled(GL11.GL_BLEND)&&!GL11.glIsEnabled(GL30.GL_RASTERIZER_DISCARD),"state program/fixed GL state");
 }
 private static boolean normalWrites(){java.nio.ByteBuffer mask=org.lwjgl.BufferUtils.createByteBuffer(4);GL30.glGetBooleani_v(GL11.GL_COLOR_WRITEMASK,1,mask);for(int i=0;i<4;i++)if(mask.get(i)==0)return false;return !GL30.glIsEnabledi(GL11.GL_BLEND,1)&&GL11.glGetInteger(GL20.GL_DRAW_BUFFER2)==GL11.GL_NONE;}
 public static Draw producer(RenderTargets t,int p){failure=null;int w=t.getCurrentWidth(),h=t.getCurrentHeight();var rt=t.get(10);int[] v=new int[4];GL11.glGetIntegerv(GL11.GL_VIEWPORT,v);int fbo=GL11.glGetInteger(GL30.GL_DRAW_FRAMEBUFFER_BINDING);
  int normalTex=GL30.glGetFramebufferAttachmentParameteri(GL30.GL_DRAW_FRAMEBUFFER,GL30.GL_COLOR_ATTACHMENT1,GL30.GL_FRAMEBUFFER_ATTACHMENT_OBJECT_NAME);var normalTarget=t.get(11);int tex=GL30.glGetFramebufferAttachmentParameteri(GL30.GL_DRAW_FRAMEBUFFER,GL30.GL_COLOR_ATTACHMENT0,GL30.GL_FRAMEBUFFER_ATTACHMENT_OBJECT_NAME);var depth=binding(p,"depthtex0");
  int normalWidth=-1,normalHeight=-1,targetWidth=-1,targetHeight=-1;
  boolean valid=proof(normalWrites(),"normal writes")&&
   proof(normalTarget!=null&&(normalWidth=normalTarget.getWidth())==w&&(normalHeight=normalTarget.getHeight())==h&&normalTarget.getInternalFormat().name().equals("RGBA32F"),"target11 size/format")&&
   proof(normalTex!=tex&&GL30.glGetFramebufferAttachmentParameteri(GL30.GL_DRAW_FRAMEBUFFER,GL30.GL_COLOR_ATTACHMENT1,GL30.GL_FRAMEBUFFER_ATTACHMENT_OBJECT_TYPE)==GL11.GL_TEXTURE&&GL30.glGetFramebufferAttachmentParameteri(GL30.GL_DRAW_FRAMEBUFFER,GL30.GL_COLOR_ATTACHMENT1,GL30.GL_FRAMEBUFFER_ATTACHMENT_TEXTURE_LEVEL)==0&&(normalTex==normalTarget.getMainTexture()||normalTex==normalTarget.getAltTexture())&&GL11.glGetInteger(GL20.GL_DRAW_BUFFER1)==GL30.GL_COLOR_ATTACHMENT1,"target11 ownership/draw buffer")&&
   proof(rt!=null&&w>=2&&h>=2&&w<=16384&&h<=16384&&(targetWidth=rt.getWidth())==w&&(targetHeight=rt.getHeight())==h&&rt.getInternalFormat().name().equals("RGBA32F")&&tex>0&&(tex==rt.getMainTexture()||tex==rt.getAltTexture())&&fbo>0&&
   GL30.glCheckFramebufferStatus(GL30.GL_DRAW_FRAMEBUFFER)==GL30.GL_FRAMEBUFFER_COMPLETE&&GL30.glGetFramebufferAttachmentParameteri(GL30.GL_DRAW_FRAMEBUFFER,GL30.GL_COLOR_ATTACHMENT0,GL30.GL_FRAMEBUFFER_ATTACHMENT_OBJECT_TYPE)==GL11.GL_TEXTURE&&GL30.glGetFramebufferAttachmentParameteri(GL30.GL_DRAW_FRAMEBUFFER,GL30.GL_COLOR_ATTACHMENT0,GL30.GL_FRAMEBUFFER_ATTACHMENT_TEXTURE_LEVEL)==0&&GL11.glGetInteger(GL20.GL_DRAW_BUFFER0)==GL30.GL_COLOR_ATTACHMENT0,"target10/FBO")&&
   proof(SolasAoContract.viewport(v,w,h,true),"producer viewport")&&proof(base(depth)&&depth.min()==depth.mag()&&depth.wrapS()==GL12.GL_CLAMP_TO_EDGE&&depth.wrapT()==GL12.GL_CLAMP_TO_EDGE&&com.pp.shaderlod.optimization.DepthTextureStorage.accepts(depth.format(),depth.depthBits(),depth.depthType())&&depth.texture()==SolasAoDepthId.current(t)&&depth.width()==w&&depth.height()==h,"depth sampler/identity")&&state(p);
  if(!valid)failure+="; program="+p+"; viewport="+Arrays.toString(v)+"; targetSize="+w+"x"+h+"; target10="+targetWidth+"x"+targetHeight+"; target11="+normalWidth+"x"+normalHeight+"; textures="+tex+","+normalTex+"; fbo="+fbo+"; depth="+depth;
  return new Draw(new SolasAoEpoch.Output(tex,normalTex,fbo,w,h,depth),valid);}
 public static boolean consumer(RenderTargets t,int p,int produced){var b=binding(p,"colortex10");var n=binding(p,"colortex11");var depth=binding(p,"depthtex0");int[]v=new int[4];GL11.glGetIntegerv(GL11.GL_VIEWPORT,v);int fbo=GL11.glGetInteger(GL30.GL_DRAW_FRAMEBUFFER_BINDING);var ao=t.get(5);var normal=t.get(11);int out=GL30.glGetFramebufferAttachmentParameteri(GL30.GL_DRAW_FRAMEBUFFER,GL30.GL_COLOR_ATTACHMENT0,GL30.GL_FRAMEBUFFER_ATTACHMENT_OBJECT_NAME);
  return ao!=null&&ao.getWidth()==t.getCurrentWidth()&&ao.getHeight()==t.getCurrentHeight()&&base(depth)&&depth.min()==depth.mag()&&depth.texture()==SolasAoDepthId.current(t)&&depth.width()==t.getCurrentWidth()&&depth.height()==t.getCurrentHeight()&&normal!=null&&(out==ao.getMainTexture()||out==ao.getAltTexture())&&fbo>0&&GL30.glCheckFramebufferStatus(GL30.GL_DRAW_FRAMEBUFFER)==GL30.GL_FRAMEBUFFER_COMPLETE&&GL11.glGetInteger(GL20.GL_DRAW_BUFFER0)==GL30.GL_COLOR_ATTACHMENT0&&base(b)&&base(n)&&b.texture()==produced&&(n.texture()==normal.getMainTexture()||n.texture()==normal.getAltTexture())&&b.format()==GL30.GL_RGBA32F&&n.format()==GL30.GL_RGBA32F&&b.width()==t.getCurrentWidth()&&b.height()==t.getCurrentHeight()&&n.width()==b.width()&&n.height()==b.height()&&b.wrapS()==GL12.GL_CLAMP_TO_EDGE&&b.wrapT()==GL12.GL_CLAMP_TO_EDGE&&n.wrapS()==GL12.GL_CLAMP_TO_EDGE&&n.wrapT()==GL12.GL_CLAMP_TO_EDGE&&SolasAoContract.viewport(v,b.width(),b.height(),false)&&state(p);}
 public static void upload(int p,boolean ready,int w,int h){int loc=GL20.glGetUniformLocation(p,"shaderlodSolasAoTargetReady");if(loc>=0)GL20.glUniform1i(loc,ready?1:0);loc=GL20.glGetUniformLocation(p,"shaderlodSolasAoTargetSize");if(loc>=0)GL20.glUniform2f(loc,ready?w:0,ready?h:0);}
}
